<article class="request-hospital request-quotation">
    <h4 class="request-hospital-name" data-hospital-name data-user-content></h4><p class="request-hospital-description" data-hospital-description data-user-content hidden></p><p class="request-hospital-address" data-hospital-address data-user-content hidden></p>
    <p class="request-quotation-label">Quotation Price (THB)</p><strong class="request-quotation-price" data-quote-price></strong>
    <p class="request-quotation-details" data-quote-details></p><p class="request-quotation-validity" data-quote-validity hidden></p>
    <div class="request-hospital-bottom"><x-requests.status-badge kind="response" /><button class="request-quote-view" data-view-quote type="button">View Details</button></div>
</article>
